    let n = n1 * 0.6 + n2 * 0.4;
    // 保持初始值在0.3-0.7之间,避免极端值
    let centered = 0.5 + (n - 0.5) * 0.4;
    
    textureStore(outputTex, coords, vec4<f32>(centered, 0.0, 0.0, 1.0));
